/* Original synthesized sound effects. No external assets. */
(function(root){'use strict';let ctx;const volume=()=>Math.max(0,Math.min(1,Number(localStorage.getItem('effectsVolume')??.85)||0));function unlock(){try{ctx=ctx||new (window.AudioContext||window.webkitAudioContext)();ctx.resume().catch(()=>{});}catch{}}function tone(f,end,t,d,amp,type='sine'){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(end,t+d);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(Math.max(.001,amp*volume()),t+.015);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+d+.02);}function play(kind){if(!ctx||ctx.state!=='running'||localStorage.getItem('muted')==='1'||!volume())return;const t=ctx.currentTime+.02;if(kind==='heartbeat'){tone(70,45,t,.18,.18);tone(80,50,t+.24,.15,.12);}else if(kind==='roar'){tone(90,38,t,.65,.12,'sawtooth');tone(135,60,t,.5,.08,'triangle');}else if(kind==='warning'){tone(440,550,t,.18,.08);tone(550,660,t+.25,.2,.08);}else if(kind==='death'){tone(330,85,t,.4,.10,'triangle');}else if(kind==='end'){[262,330,392,523].forEach((f,i)=>tone(f,f,t+i*.12,.24,.07));}}root.Effects={unlock,play,volume,setVolume:v=>localStorage.setItem('effectsVolume',String(v))};})(globalThis);
